head.script:
scwin.fn_GetPar, scwin.fn_SetPar;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnLoadError = function() {
    try {
        alert($c.stf.getMessageParam("MSG-0002"));
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS05201.dts_List_OnLoadError" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_Close_onclick = function(e) {
    try {
        $c.win.closePopup();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS05201.btn_Close_onclick" });
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name gform_onload
 * @description 파라미터추출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.gform_onload = async function() {
    // 파라미터추출

    const prt = $c.win.getParent();
    if (prt !== undefined) {

        scwin.fn_GetPar = prt.scwin.fn_GetPar;
    }

    if (scwin.fn_GetPar !== undefined) {
        const arrPar = new Array();

        scwin.fn_GetPar(arrPar);

        // 첨부문서조회
        url += "&service=krx.lds.stf.listingcommon.services.ListingCommonApp";
        url += "&outputMessageId=BNS_BYMM_ISU_DTL";
        url += "&queryId=lds.stf.bnspack.select.listBymmIsuDtl";
        url += "&SCREN_ID=" + "ULDBNS05201.gfm";
        url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        url += "&{P}V_BND_APPL_ID=" + arrPar[0].BND_APPL_ID; // 채권신청ID
        url += "&{P}V_BND_LIST_PROCS_TP_CD=" + arrPar[0].BND_LIST_PROCS_TP_CD; // 채권처리구분(1:신청,2:접수)
        const sbmOptions = {
            id : "sbm_dts_List",
            action : "/listingCommon.do",
            ref : "",
            target : "dts_List=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    }
};
